/**
 * Caches the Pyodide runtime so repeat visits skip the multi-megabyte
 * download. Generated by scripts/copy-pyodide.mjs — edit the template, not
 * public/sw.js.
 *
 * The cache name carries the Pyodide version, so upgrading the package
 * invalidates the old runtime instead of serving a stale mix of files.
 */
const CACHE = "pyodide-__PYODIDE_VERSION__";
// Substituted at generation time — "/pyodide/" in dev, "<base>pyodide/" for a
// subpath deploy. A literal here would silently stop matching once deployed.
const RUNTIME_PATH = "__BASE__pyodide/";

self.addEventListener("install", () => {
  // The runtime is fetched on demand rather than precached: the app should
  // become interactive without waiting for 13 MB to land.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name.startsWith("pyodide-") && name !== CACHE).map((name) => caches.delete(name)),
      );
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);

  // Only the runtime is ours to serve; everything else goes to the network
  // untouched so dev reloads and app updates behave normally.
  if (
    event.request.method !== "GET" ||
    url.origin !== self.location.origin ||
    !url.pathname.startsWith(RUNTIME_PATH)
  ) {
    return;
  }

  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(event.request);
      if (hit) return hit;

      const response = await fetch(event.request);
      // Opaque or failed responses are not worth persisting.
      if (response.ok && response.type === "basic") {
        cache.put(event.request, response.clone());
      }
      return response;
    })(),
  );
});
